0.048,"33252":0.048,"33412":0.0144,"33428":0.0144,"33432":0.0144,"33436":0.0144,"33611":0.069,"33734":0.02152,"33738":0.03228,"33816":0.05676,"33857":0.072,"34027":0.042,"34263":0.028,"34296":0.00168,"34298":0.00168,"34320":0.042,"34410":0.00588,"34420":0.01,"34429":0.01,"34432":0.05676}}'::jsonb->v.q->>u.sku_code)::numeric,0) as hl_factor
 from universe u join versions v on v.id=u.version_id left join sources s on s.version_id=u.version_id and s.sku_code=u.sku_code
 left join stock_policy_items p on p.sku_code=u.sku_code and p.version_id=(select id from stock_policy_versions where code='R2/2026')
), calculated as (
 select *,case when avg_hl is null then null when upper(unit_code)='L' then avg_hl*100
 when volume_caixas>=0 then volume_caixas/days_worked
 when hl_factor>0 then avg_hl/hl_factor end as avg_qty
 from prepared
)
insert into stock_policy_items(version_id,sku_code,sku_name,curve_class,unit_code,avg_daily_boxes,avg_daily_qty,avg_daily_hl,avg_daily_pallets,min_days,objective_days,max_days,min_qty,objective_qty,max_qty,min_hl,objective_hl,max_hl,out_qty,over_qty,policy_source,source_file,suggestion_basis,review_flags,review_note)
select version_id,sku_code,sku_name,curve_class,unit_code,
 case when upper(unit_code)='CX' then avg_qty end,avg_qty,avg_hl,
 case when valid_days then volume_pallets/days_worked end,3,5,null,
 avg_qty*3,avg_qty*5,null,avg_hl*3,avg_hl*5,null,avg_qty*3,null,
 'TRIMESTRAL_ABC_PARCIAL',source_file,
 'Média = volume da curva de referência / dias trabalhados. Um registro por SKU; Picking não é somado ao Regulador. Mínimo = 3 dias; objetivo = 5 dias. Máximo não copiado da política semestral e não aplicado ao OOR.',
 jsonb_build_array('PUXADA_TRIMESTRAL_INCOMPLETA','CONFIRMAR_PERIODO_VENDAS')
 ||case when not coalesce(valid_days,false) then jsonb_build_array('DIAS_BASE_INVALIDOS') else '[]'::jsonb end
 ||case when volume_hl is null then jsonb_build_array('SEM_BASE_VENDAS_SKU') else '[]'::jsonb end
 ||case when avg_hl>0 and avg_qty is null then jsonb_build_array('CONVERSAO_PENDENTE') else '[]'::jsonb end
 ||case when q='1' then jsonb_build_array('ESTOQUE_2025_PENDENTE') else '[]'::jsonb end,
 case when not coalesce(valid_days,false) then 'Dias trabalhados incompatíveis com o trimestre-base. Informe o 03.05.19 do período correto e seus dias trabalhados.' else 'Máximo e período-base aguardam validação das bases trimestrais.' end
from calculated on conflict(version_id,sku_code) do nothing;
update stock_policy_versions v set calculation_metadata=v.calculation_metadata||jsonb_build_object(
 'items',(select count(*) from stock_policy_items p where p.version_id=v.id),
 'demand_items',(select count(*) from stock_policy_items p where p.version_id=v.id and p.avg_daily_qty is not null),
 'pending_maximum_items',(select count(*) from stock_policy_items p where p.version_id=v.id and p.max_qty is null),
 'days_worked',(select days_worked from abc_months m where m.reference_month=v.effective_start),
 'stock_days',(select count(distinct reference_date) from stock_oor_daily_detail d where d.reference_date between v.review_start and v.review_end),
 'pull_days',(select count(distinct report_date) from receiving_system_020501 d where d.report_date between v.review_start and v.review_end)
 ),updated_at=now()
where v.code in('T1/2026','T2/2026','T3/2026','T4/2026') and v.status='draft';
insert into stock_policy_audit_log(version_id,action,details)
select id,'GENERATE',jsonb_build_object('method','quarterly-abc-demand-v1','oor_enabled',false,'history_preserved',true,'readiness','partial')
from stock_policy_versions where code in('T1/2026','T2/2026','T3/2026','T4/2026');
commit;
